const raw = $json.body || $json.data || '';
const markdown = String(raw).replace(/\u0000/g, '').trim();
const headingMatch = markdown.match(/^#\s+(.+)$/m);
const title = headingMatch ? headingMatch[1].trim() : 'LeeWu Maritime content';
return [{ json: {
  blog_url: $('On form submission2').first().json.blog_url,
  title,
  data: { markdown: markdown.slice(0, 120000) },
  topic: markdown.slice(0, 120000),
  source_type: 'blog_url',
  question: 'Summarize this source and generate an LeeWu Maritime LinkedIn post plus image prompt'
} }];

return [{ json: {
  blog_url: $json.blog_url,
  title: $json.title,
  question: $json.question,
  source_text: $json.data?.markdown || $json.topic || '',
  data: $json.data,
  client_name: 'LeeWu Maritime Services',
  source_type: $json.source_type || 'blog_url'
} }];

const out = $json.output || $json;
const payload = typeof out === 'string' ? { summary: out } : out;
const title = payload.title || $('Prepare LeeWu Maritime prompt2').first().json.title || 'LeeWu Maritime content';
const summary = payload.summary || '';
const post_text = payload.customized_post_text || payload.post_text || summary;
const llm_image_prompt = payload.llm_image_prompt || 'Technical maritime workflow illustration, navy and orange, clean blueprint style';
return [{ json: {
  created_at: new Date().toISOString(),
  blog_url: $('Prepare LeeWu Maritime prompt2').first().json.blog_url,
  title,
  summary,
  post_text,
  llm_image_prompt,
  source_notes: payload.source_notes || [],
  published: false,
  confirmation: 'Ready for review'
} }];

