  data: $json.data,
  client_name: 'LeeWu Maritime Services',
  source_type: $json.source_type || 'blog_url'
} }];

const out = $json.output || $json;
const payload = typeof out === 'string' ? { summary: out } : out;
const title = payload.title || $('Prepare LeeWu Maritime prompt').first().json.title || 'LeeWu Maritime content';
const summary = payload.summary || '';
const post_text = payload.customized_post_text || payload.post_text || summary;
const llm_image_prompt = payload.llm_image_prompt || 'Technical maritime workflow illustration, navy and orange, clean blueprint style';
return [{ json: {
  created_at: new Date().toISOString(),
  blog_url: $('Prepare LeeWu Maritime prompt').first().json.blog_url,
  title,
  summary,
  post_text,
  llm_image_prompt,
  source_notes: payload.source_notes || [],
  published: false,
  confirmation: 'Ready for review'
} }];

const agentOut = $json.output || $json.text || $json.answer || $json;
const finalPrompt = typeof agentOut === 'string' ? agentOut : (agentOut.output || agentOut.text || agentOut.answer || JSON.stringify(agentOut));
const pkg = $('Create content package').first().json;
return [{ json: { ...pkg, llm_image_prompt: String(finalPrompt).trim() || pkg.llm_image_prompt } }];

const imageUrl =
  $json.choices?.[0]?.message?.images?.[0]?.image_url?.url || '';

if (!imageUrl) {
  throw new Error('No image found in OpenRouter response. Check choices[0].message.images[0].image_url.url');
}

const base64 = imageUrl.includes(',')
  ? imageUrl.split(',')[1]
  : imageUrl;

return [
  {
    json: {
      ...$json,
      image_base64: base64,
      image_data_url: imageUrl
    }
  }
];
